/* Atlético Madrid DNA — rojiblanco fine stripes on warm plaster, colchonero navy */
.theme-atletico-madrid {
  --bg: oklch(0.977 0.003 67.8);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.938 0.008 56.3);
  --fg: oklch(0.328 0.117 276.6);
  --fg-muted: oklch(0.626 0.008 67.7);
  --accent: oklch(0.591 0.234 27.3);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.328 0.117 276.6);
  --line: oklch(0.889 0.011 63.3);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.591 0.234 27.3);
  --radius: 0.25rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Barlow Condensed", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-atletico-madrid h1,
.theme-atletico-madrid h2,
.theme-atletico-madrid h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-atletico-madrid { --font-ui: var(--font-display); }
.theme-atletico-madrid h1, .theme-atletico-madrid h2 { text-transform: uppercase; }
.theme-atletico-madrid button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-atletico-madrid { background-image: repeating-linear-gradient(90deg, oklch(0.55 0.19 25 / 7%) 0 22px, transparent 22px 44px); background-size: 100% 300px; background-repeat: no-repeat; }
.theme-atletico-madrid h1 { color: var(--accent-2); font-weight: 700; }
.theme-atletico-madrid h1 em, .theme-atletico-madrid h2 { color: var(--accent); }


/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
